  <section class="sec rise first" style="--i:2"><div class="sh"><h3>A csapat képe rólad</h3></div><div class="card deep"><div class="mwempty">${['alvas','mozgas','etkezes','kozerzet','mezo'].map(k=>`<div>${G(TM[k][1],'cream')}<span class="tb"></span><small>0 / 8 nap</small></div>`).join('')}</div></div></section>
